class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total_imbalance = 0

        # Generate all subarrays
        for start in range(n):
            current_subarray = []
            for end in range(start, n):
                # Add current element to subarray
                current_subarray.append(nums[end])

                # Sort the current subarray
                sorted_subarray = sorted(current_subarray)

                # Count imbalance number (gaps > 1 between adjacent elements)
                imbalance = 0
                for i in range(len(sorted_subarray) - 1):
                    if sorted_subarray[i + 1] - sorted_subarray[i] > 1:
                        imbalance += 1

                total_imbalance += imbalance

        return total_imbalance

