H, W = map(int, input().split())

# Create grid - True means cookie present, False means removed
grid = []
for _ in range(H):
    row = input().strip()
    grid.append(list(row))

# Convert to boolean for easier manipulation
present = [[True] * W for _ in range(H)]

# Continue until no more cookies are marked
changed = True
while changed:
    changed = False

    # Check rows for uniform colors
    rows_to_remove = []
    for i in range(H):
        if sum(present[i]) >= 2:  # At least 2 cookies remaining
            # Check if all remaining cookies in this row have the same color
            colors = set()
            for j in range(W):
                if present[i][j]:
                    colors.add(grid[i][j])

            if len(colors) == 1:  # All same color
                rows_to_remove.append(i)

    # Check columns for uniform colors
