class Solution:
    def minGroupsForValidAssignment(self, nums: List[int]) -> int:
        from collections import Counter

        n = len(nums)
        freq = Counter(nums)

        # Try different number of groups from 1 to n
        for g in range(1, n + 1):
            # Calculate the base group size
            if n == 0:
                return 0
            base_size = n // g
            larger_size = base_size + 1

            # Number of groups of larger size
            larger_groups = n % g
            # Number of groups of base size
            base_groups = g - larger_groups

            # For each frequency, check if we can distribute it
            valid = True
            for count in freq.values():
                if count == 0:
                    continue

                # We need to represent 'count' as a * base_size + b * larger_size
                # where a <= base_groups, b <= larger_groups
                found = False

                # Try all possible number of larger_size groups
                # Maximum b is limited by both the available larger_groups and the count
                if larger_size == 0:
                    # This shouldn't happen since n >= 1 and g >= 1
                    if count == 0:
                        found = True
                    else:
                        found = False
                else:
                    max_b = min(larger_groups, count // larger_size)

                    for b in range(max_b + 1):
                        remaining = count - b * larger_size
                        if remaining < 0:
                            break

                        # Remaining must be divisible by base_size
                        if base_size == 0:
                            if remaining == 0:
                                found = True
                                break
                        else:
                            if remaining % base_size == 0:
                                a = remaining // base_size
                                if a <= base_groups:
                                    found = True
                                    break

                if not found:
                    valid = False
                    break

            if valid:
                return g

        return n
